import { test as base } from "@playwright/test";

import { e2eConfig, PARALLEL_TAG_PATTERN } from "../config.ts";
import type { Actor } from "../lib/actors.ts";
import { storageStatePath } from "../lib/auth.ts";
import { ensureScenario, restoreScenario } from "../lib/seed.ts";

interface E2eOptions {
  /**
   * Who the browser is signed in as. `anonymous` carries no session, for specs that sign
   * in through the UI themselves.
   */
  actor: Actor;
  /** The database state this spec starts from. See `scenarios/`. */
  scenario: string;
}

interface E2eFixtures {
  seed: void;
}

const config = e2eConfig();

export const test = base.extend<E2eOptions & E2eFixtures>({
  actor: ["admin", { option: true }],
  scenario: ["default", { option: true }],

  /**
   * Puts the database back before the test runs.
   *
   * `storageState` depends on this rather than it being an `auto` fixture, because the
   * ordering is the point: the reset has to finish before the browser context exists, or
   * the first page load races a truncated database.
   *
   * A test tagged `parallel()` skips the reset entirely - that is what lets those run in
   * parallel with each other. The database their group shares was restored once, by the
   * group's `restore:<scenario>` project.
   */
  seed: async ({ scenario }, provide, testInfo) => {
    /*
     * A tagged test runs on the database its group's restore project put in place, and
     * resetting here would pull it out from under the tests running alongside.
     */
    if (testInfo.tags.some(tag => PARALLEL_TAG_PATTERN.test(tag))) {
      await provide();

      return;
    }

    const dumpPath = await ensureScenario(config, scenario);

    restoreScenario(config, dumpPath);

    await provide();
  },

  storageState: async ({ actor, seed }, provide) => {
    void seed;

    if (actor === "anonymous") {
      await provide(undefined);

      return;
    }

    await provide(storageStatePath(config, actor));
  },
});

export { expect } from "@playwright/test";
import type { E2eConfig } from "../config.ts";
import { adminToken, assertNoMutationErrors, gql } from "../lib/graphql.ts";
import { step } from "../lib/progress.ts";
import type { Scenario } from "./scenario.ts";

/**
 * The default scenario plus the order states the order specs start from.
 *
 * `populatedb` alone cannot serve them: its orders are random (channel, customer, a 10%
 * chance of being unconfirmed, fulfilled whenever they happen to be paid) and its catalogue
 * promotions hit random products. So this scenario brings its own products at known prices,
 * one known customer, one promotion of each kind, and orders a spec can look up by name -
 * see `findOrderId`. Everything lives in one channel.
 *
 * `populatedb`'s own promotions are deleted, so no price here depends on which products
 * its random draw picked.
 */
export const ORDERS_SCENARIO = "orders";

/** Marks orders as paid with a transaction - `populatedb`'s default. */
export const CHANNEL = { slug: "default-channel", name: "Channel-USD" } as const;

export const CUSTOMER = {
  email: "e2e.customer@example.com",
  firstName: "Ada",
  lastName: "Lovelace",
};

const CUSTOMER_ADDRESS = {
  firstName: CUSTOMER.firstName,
  lastName: CUSTOMER.lastName,
  streetAddress1: "69 W 9th Street",
  city: "New York",
  postalCode: "10001",
  country: "US",
  countryArea: "NY",
  phone: "+12125771133",
};

/** Prices in the channel's currency, USD. */
export const PRODUCTS = {
  /** Discounted by the catalogue promotion. */
  tee: { name: "E2E Tee", sku: "e2e-tee", price: 10 },
  hoodie: { name: "E2E Hoodie", sku: "e2e-hoodie", price: 50 },
} as const;

export const PROMOTIONS = {
  catalogue: { name: "E2E Tee sale", percent: 20 },
  order: { name: "E2E big basket", percent: 10, subtotalAtLeast: 30 },
} as const;

/**
 * Orders, keyed by what a spec needs from them. Each carries its key as `e2e` metadata,
 * which is how `findOrderId` finds it - ids differ per build of the dump.
 */
export const SCENARIO_ORDERS = {
  /** One tee, unpaid and unfulfilled. */
  unpaid: { paid: false },
  /** One tee, paid and fulfilled. */
  fulfilled: { paid: true },
} as const;

export type ScenarioOrder = keyof typeof SCENARIO_ORDERS;

type Mutate = <T extends Record<string, unknown>>(
  name: string,
  query: string,
  variables?: Record<string, unknown>,
) => Promise<T>;

/** One mutation, failing on the payload's `errors` - see `assertNoMutationErrors`. */
const mutator =
  (config: E2eConfig, token: string): Mutate =>
  async (name, query, variables = {}) => {
    const data = await gql<Record<string, { errors?: unknown }>>(config, query, variables, token);

    assertNoMutationErrors(name, data[name]?.errors);

    return data[name] as never;
  };

const lookUpShop = async (config: E2eConfig, token: string) => {
  const data = await gql<{
    channel: { id: string };
    categories: { edges: { node: { id: string } }[] };
    promotions: { edges: { node: { id: string } }[] };
    warehouses: {
      edges: {
        node: {
          id: string;
          shippingZones: {
            edges: { node: { countries: { code: string }[]; channels: { slug: string }[] } }[];
          };
        };
      }[];
    };
  }>(
    config,
    `query($channel: String!) {
      channel(slug: $channel) { id }
      categories(first: 1) { edges { node { id } } }
      promotions(first: 100) { edges { node { id } } }
      warehouses(first: 100) {
        edges { node { id shippingZones(first: 100) { edges { node { countries { code } channels { slug } } } } } }
      }
    }`,
    { channel: CHANNEL.slug },
    token,
  );

  /* Stock is only sellable through a zone that covers the address in the order's channel. */
  const warehouse = data.warehouses.edges.find(({ node }) =>
    node.shippingZones.edges.some(
      ({ node: zone }) =>
        zone.countries.some(({ code }) => code === CUSTOMER_ADDRESS.country) &&
        zone.channels.some(({ slug }) => slug === CHANNEL.slug),
    ),
  );

  if (!warehouse) {
    throw new Error(`no warehouse ships to ${CUSTOMER_ADDRESS.country} in ${CHANNEL.slug}`);
  }

  return {
    channelId: data.channel.id,
    categoryId: data.categories.edges[0].node.id,
    promotionIds: data.promotions.edges.map(({ node }) => node.id),
    warehouseId: warehouse.node.id,
  };
};

type Shop = Awaited<ReturnType<typeof lookUpShop>>;

const createProducts = async (mutate: Mutate, shop: Shop) => {
  const { productType } = await mutate<{ productType: { id: string } }>(
    "productTypeCreate",
    `mutation($input: ProductTypeInput!) {
      productTypeCreate(input: $input) { productType { id } errors { field code message } }
    }`,
    {
      input: { name: "E2E Simple", kind: "NORMAL", hasVariants: false, isShippingRequired: true },
    },
  );
  const variantIds: Record<keyof typeof PRODUCTS, string> = { tee: "", hoodie: "" };

  for (const [key, product] of Object.entries(PRODUCTS) as [
    keyof typeof PRODUCTS,
    (typeof PRODUCTS)[keyof typeof PRODUCTS],
  ][]) {
    const created = await mutate<{ product: { id: string } }>(
      "productCreate",
      `mutation($input: ProductCreateInput!) {
        productCreate(input: $input) { product { id } errors { field code message } }
      }`,
      { input: { name: product.name, productType: productType.id, category: shop.categoryId } },
    );
    const { productVariant } = await mutate<{ productVariant: { id: string } }>(
      "productVariantCreate",
      `mutation($input: ProductVariantCreateInput!) {
        productVariantCreate(input: $input) { productVariant { id } errors { field code message } }
      }`,
      {
        input: {
          product: created.product.id,
          sku: product.sku,
          attributes: [],
          trackInventory: true,
          stocks: [{ warehouse: shop.warehouseId, quantity: 1000 }],
        },
      },
    );

    await mutate(
      "productChannelListingUpdate",
      `mutation($id: ID!, $input: ProductChannelListingUpdateInput!) {
        productChannelListingUpdate(id: $id, input: $input) { errors { field code message } }
      }`,
      {
        id: created.product.id,
        input: {
          updateChannels: [
            {
              channelId: shop.channelId,
              isPublished: true,
              visibleInListings: true,
              isAvailableForPurchase: true,
              addVariants: [productVariant.id],
            },
          ],
        },
      },
    );
    await mutate(
      "productVariantChannelListingUpdate",
      `mutation($id: ID!, $input: [ProductVariantChannelListingAddInput!]!) {
        productVariantChannelListingUpdate(id: $id, input: $input) { errors { field code message } }
      }`,
      {
        id: productVariant.id,
        input: [{ channelId: shop.channelId, price: product.price }],
      },
    );

    variantIds[key] = productVariant.id;
  }

  return variantIds;
};

const createPromotions = async (mutate: Mutate, shop: Shop, teeProductId: string) => {
  if (shop.promotionIds.length > 0) {
    await mutate(
      "promotionBulkDelete",
      `mutation($ids: [ID!]!) { promotionBulkDelete(ids: $ids) { errors { field code message } } }`,
      { ids: shop.promotionIds },
    );
  }

  const create = (input: Record<string, unknown>) =>
    mutate(
      "promotionCreate",
      `mutation($input: PromotionCreateInput!) {
        promotionCreate(input: $input) { errors { field code message } }
      }`,
      { input },
    );

  await create({
    name: PROMOTIONS.catalogue.name,
    type: "CATALOGUE",
    rules: [
      {
        channels: [shop.channelId],
        rewardValueType: "PERCENTAGE",
        rewardValue: PROMOTIONS.catalogue.percent,
        cataloguePredicate: { productPredicate: { ids: [teeProductId] } },
      },
    ],
  });
  await create({
    name: PROMOTIONS.order.name,
    type: "ORDER",
    rules: [
      {
        channels: [shop.channelId],
        rewardType: "SUBTOTAL_DISCOUNT",
        rewardValueType: "PERCENTAGE",
        rewardValue: PROMOTIONS.order.percent,
        orderPredicate: {
          discountedObjectPredicate: {
            baseSubtotalPrice: { range: { gte: PROMOTIONS.order.subtotalAtLeast } },
          },
        },
      },
    ],
  });
};

const createOrder = async (
  mutate: Mutate,
  {
    ref,
    channelId,
    customerId,
    variantId,
    warehouseId,
    paid,
  }: {
    ref: ScenarioOrder;
    channelId: string;
    customerId: string;
    variantId: string;
    warehouseId: string;
    paid: boolean;
  },
) => {
  const { order: draft } = await mutate<{
    order: { id: string; shippingMethods: { id: string }[] };
  }>(
    "draftOrderCreate",
    `mutation($input: DraftOrderCreateInput!) {
      draftOrderCreate(input: $input) {
        order { id shippingMethods { id } }
        errors { field code message }
      }
    }`,
    {
      input: {
        channelId,
        user: customerId,
        lines: [{ variantId, quantity: 1 }],
        shippingAddress: CUSTOMER_ADDRESS,
        billingAddress: CUSTOMER_ADDRESS,
        metadata: [{ key: "e2e", value: ref }],
      },
    },
  );

  await mutate(
    "draftOrderUpdate",
    `mutation($id: ID!, $input: DraftOrderInput!) {
      draftOrderUpdate(id: $id, input: $input) { errors { field code message } }
    }`,
    { id: draft.id, input: { shippingMethod: draft.shippingMethods[0].id } },
  );

  const { order } = await mutate<{ order: { id: string; lines: { id: string }[] } }>(
    "draftOrderComplete",
    `mutation($id: ID!) {
      draftOrderComplete(id: $id) { order { id lines { id } } errors { field code message } }
    }`,
    { id: draft.id },
  );

  if (!paid) {
    return;
  }

  await mutate(
    "orderMarkAsPaid",
    `mutation($id: ID!) { orderMarkAsPaid(id: $id) { errors { field code message } } }`,
    { id: order.id },
  );
  await mutate(
    "orderFulfill",
    `mutation($order: ID!, $input: OrderFulfillInput!) {
      orderFulfill(order: $order, input: $input) { errors { field code message } }
    }`,
    {
      order: order.id,
      input: {
        notifyCustomer: false,
        lines: order.lines.map(line => ({
          orderLineId: line.id,
          stocks: [{ warehouse: warehouseId, quantity: 1 }],
        })),
      },
    },
  );
};

export const ordersScenario: Scenario = {
  name: ORDERS_SCENARIO,
  parent: "default",
  build: async (config, getAdminToken) => {
    const token = await getAdminToken();
    const mutate = mutator(config, token);
    const shop = await lookUpShop(config, token);

    const variantIds = await step("creating products", () => createProducts(mutate, shop));
    const teeProductId = (
      await gql<{ productVariant: { product: { id: string } } }>(
        config,
        `query($id: ID!) { productVariant(id: $id) { product { id } } }`,
        { id: variantIds.tee },
        token,
      )
    ).productVariant.product.id;

    await step("replacing the promotions", () => createPromotions(mutate, shop, teeProductId));

    const { user } = await mutate<{ user: { id: string } }>(
      "customerCreate",
      `mutation($input: UserCreateInput!) {
        customerCreate(input: $input) { user { id } errors { field code message } }
      }`,
      {
        input: {
          ...CUSTOMER,
          defaultShippingAddress: CUSTOMER_ADDRESS,
          defaultBillingAddress: CUSTOMER_ADDRESS,
        },
      },
    );

    await step("creating orders", async () => {
      for (const [ref, { paid }] of Object.entries(SCENARIO_ORDERS)) {
        await createOrder(mutate, {
          ref: ref as ScenarioOrder,
          channelId: shop.channelId,
          customerId: user.id,
          variantId: variantIds.tee,
          warehouseId: shop.warehouseId,
          paid,
        });
      }
    });
  },
};

/**
 * The id of one of `SCENARIO_ORDERS` in the restored database. A read, so it is safe at
 * test time; ids are not constants because every build of the dump mints new ones.
 */
export const findOrderId = async (config: E2eConfig, ref: ScenarioOrder): Promise<string> => {
  const data = await gql<{ orders: { edges: { node: { id: string } }[] } }>(
    config,
    `query($ref: String!) {
      orders(first: 1, filter: { metadata: [{ key: "e2e", value: $ref }] }) { edges { node { id } } }
    }`,
    { ref },
    await adminToken(config),
  );
  const [order] = data.orders.edges;

  if (!order) {
    throw new Error(`the "${ORDERS_SCENARIO}" scenario has no order "${ref}"`);
  }

  return order.node.id;
};
import { ADMIN, STAFF_PASSWORD } from "../config.ts";

/**
 * `populatedb` mints one staff user per permission, deriving the address from the
 * permission codename - `manage_gift_card` becomes `gift.card.manager@example.com`
 * (see `create_staffs` in Saleor's `saleor/core/utils/random_data.py`). Each lands in a
 * group holding that single permission, which is what makes them useful for asserting
 * what the dashboard hides.
 *
 * `admin` is the superuser `populatedb --createsuperuser` creates. `anonymous` carries
 * no stored session at all - for specs that sign in through the UI themselves.
 */
export const PERMISSION_ACTORS = {
  app: "app.manager@example.com",
  channel: "channel.manager@example.com",
  customer: "user.manager@example.com",
  discount: "discount.manager@example.com",
  giftCard: "gift.card.manager@example.com",
  order: "order.manager@example.com",
  page: "page.manager@example.com",
  plugin: "plugin.manager@example.com",
  product: "product.manager@example.com",
  productTypeAndAttribute: "product.type.and.attribute.manager@example.com",
  settings: "setting.manager@example.com",
  shipping: "shipping.manager@example.com",
  staff: "staff.manager@example.com",
  translations: "translation.manager@example.com",
} as const;

export type PermissionActor = keyof typeof PERMISSION_ACTORS;

/**
 * Deliberately open beyond the permission users: a scenario that seeds its own staff
 * member (two permissions, deactivated, no group) names it here without touching this map.
 */
export type Actor = PermissionActor | "admin" | "anonymous" | (string & {});

export const credentialsFor = (actor: Actor): { email: string; password: string } => {
  if (actor === "admin") {
    return ADMIN;
  }

  if (actor === "anonymous") {
    throw new Error("the anonymous actor has no credentials");
  }

  const email = PERMISSION_ACTORS[actor as PermissionActor] ?? actor;

  return { email, password: STAFF_PASSWORD };
};

export const permissionActors = Object.keys(PERMISSION_ACTORS) as PermissionActor[];
import { type Page } from "@playwright/test";

export interface AddressFields {
  firstName: string;
  lastName: string;
  streetAddress1: string;
  city: string;
  postalCode: string;
  /** As the country picker lists it, e.g. "United States of America". */
  country: string;
  /** As the country-area picker lists it, e.g. "New York". */
  countryArea: string;
}

/**
 * The address dialog orders open for a customer's shipping and billing address - from
 * "Edit" on either section, and after assigning a customer to a draft. Ported from the
 * legacy `AddressDialog` and `AddressForm`; the field ids are unchanged.
 */
export class AddressDialog {
  readonly dialog = this.page.getByRole("dialog");

  readonly customerAddressOption = this.dialog.getByRole("radio", {
    name: "Use one of customer addresses",
  });

  readonly newAddressOption = this.dialog.getByRole("radio", { name: "Add new address" });

  readonly firstNameInput = this.page.getByTestId("first-name-input");

  readonly lastNameInput = this.page.getByTestId("last-name-input");

  readonly streetAddress1Input = this.page.getByTestId("address-line-1-input");

  readonly cityInput = this.page.getByTestId("city-input");

  readonly postalCodeInput = this.page.getByTestId("zip-input");

  readonly countryInput = this.page.getByTestId("address-edit-country-select-field");

  readonly countryAreaInput = this.page.getByTestId("address-edit-country-area-field");

  readonly option = this.page.getByTestId("select-option");

  readonly sameForBillingCheckbox = this.dialog.getByRole("checkbox", {
    name: "Set the same for billing address",
  });

  readonly submitButton = this.dialog.getByTestId("submit");

  constructor(readonly page: Page) {}

  async useCustomerAddress() {
    await this.customerAddressOption.click();
    await this.save();
  }

  /** Fills an empty form - a customer with no address book lands on one directly. */
  async fillNewAddress(address: AddressFields) {
    await this.firstNameInput.fill(address.firstName);
    await this.lastNameInput.fill(address.lastName);
    await this.streetAddress1Input.fill(address.streetAddress1);
    await this.cityInput.fill(address.city);
    await this.postalCodeInput.fill(address.postalCode);
    await this.countryInput.fill(address.country);
    await this.option.filter({ hasText: address.country }).first().click();
    await this.countryAreaInput.fill(address.countryArea);
    await this.option.filter({ hasText: new RegExp(`^${address.countryArea}$`) }).click();
  }

  /**
   * "Add new address" starts from the order's current address, so a change is only the
   * fields that differ.
   */
  async changeAddress(changes: Pick<AddressFields, "firstName" | "streetAddress1">) {
    await this.newAddressOption.click();
    await this.firstNameInput.fill(changes.firstName);
    await this.streetAddress1Input.fill(changes.streetAddress1);
    await this.save();
  }

  async save() {
    await this.submitButton.click();
    await this.dialog.waitFor({ state: "hidden" });
  }
}
import { expect, type Page } from "@playwright/test";

import { AddressDialog } from "./addressDialog.ts";

/**
 * A draft order, from creating it on either list to finalizing it. Ported from the
 * legacy `DraftOrdersPage`, `OrderCreateDialog` and `AddProductsDialog`, reworked for the
 * current customer flow: "Change customer" and then an address dialog, rather than a
 * customer search on the page itself.
 */
export class DraftOrderPage {
  readonly addressDialog = new AddressDialog(this.page);

  readonly dialog = this.page.getByRole("dialog");

  readonly createOrderButton = this.page.getByTestId("create-order-button");

  readonly createDraftButton = this.page.getByTestId("create-draft-order-button");

  readonly channelInput = this.page.getByTestId("channel-autocomplete");

  readonly option = this.page.getByTestId("select-option");

  readonly statusInfo = this.page.getByTestId("status-info");

  readonly addProductsButton = this.page.getByTestId("add-products-button");

  readonly productRow = this.page.getByTestId("product");

  readonly variantRow = this.page.getByTestId("variant");

  readonly confirmProductsButton = this.page.getByTestId("confirm-button");

  readonly changeCustomerButton = this.page.getByTestId("change-customer");

  readonly customerInput = this.page.getByTestId("select-customer");

  readonly customerSection = this.page.getByTestId("customer-email-section");

  readonly shippingAddressSection = this.page.getByTestId("shipping-address-section");

  readonly billingAddressSection = this.page.getByTestId("billing-address-section");

  readonly setShippingMethodButton = this.page.getByTestId("add-shipping-carrier");

  readonly shippingMethodSelect = this.page.getByTestId("shipping-method-select");

  readonly confirmShippingButton = this.page.getByTestId("confirm-button");

  readonly total = this.page.getByTestId("order-total");

  readonly discountToggle = this.page.getByTestId("discount-section-toggle");

  readonly summary = this.page.getByTestId("OrderSummary");

  readonly finalizeButton = this.page.getByTestId("button-bar-confirm");

  constructor(readonly page: Page) {}

  /** Both lists create the same draft; they differ only in where the button lives. */
  async create({ from, channel }: { from: "orders" | "drafts"; channel: string }) {
    if (from === "orders") {
      await this.page.goto("/orders");
      await this.createOrderButton.click();
    } else {
      await this.page.goto("/orders/drafts");
      await this.createDraftButton.click();
    }

    await this.channelInput.click();
    await this.option.filter({ hasText: channel }).click();
    await this.dialog.getByTestId("submit").click();
    await expect(this.statusInfo).toHaveText("Draft");
  }

  /**
   * Searches by name - the search does not match SKUs - and waits for the list to narrow to
   * that one product: until the search lands the list re-renders, and a checkbox ticked in
   * the unfiltered one is detached from under the click.
   */
  async addProduct({ name, sku }: { name: string; sku: string }) {
    await this.addProductsButton.click();
    await this.dialog.getByRole("textbox").fill(name);
    await expect(this.productRow).toHaveCount(1);
    await this.variantRow
      .filter({ hasText: `SKU ${sku}` })
      .getByRole("checkbox")
      .click();
    await this.confirmProductsButton.click();
    await this.dialog.waitFor({ state: "hidden" });
  }

  /**
   * Picks an existing customer, or types an email no customer has - the picker then offers
   * "Use email: ...". Either way the address dialog follows.
   */
  async assignCustomer(email: string) {
    await this.changeCustomerButton.click();
    await this.customerInput.fill(email);
    await this.option.filter({ hasText: email }).click();
    await this.dialog.getByTestId("submit").click();
  }

  async setFirstShippingMethod() {
    await this.setShippingMethodButton.click();
    await this.shippingMethodSelect.click();
    await this.option.filter({ hasNotText: "No shipping method" }).first().click();
    await this.confirmShippingButton.click();
    await this.dialog.waitFor({ state: "hidden" });
  }

  /** Lands on the order it became, which no longer lives under `/orders/drafts/`. */
  async finalize() {
    await this.finalizeButton.click();
    await this.page.waitForURL(url => !url.pathname.includes("/drafts/"));
  }
}
import { expect, type Page } from "@playwright/test";

/**
 * Ported from the legacy suite. Its "welcome to your Store Dashboard" assertion was
 * dropped: `home-header` no longer exists anywhere in `src/` - the home page was replaced
 * - so that check could only ever have passed against an old dashboard.
 *
 * Signed-in is asserted on the sidebar's user menu instead. It renders only for an
 * authenticated user, and unlike the home page's contents it does not change with whatever
 * the current homepage happens to promote.
 */
export class HomePage {
  readonly userMenu = this.page.getByTestId("userMenu");

  constructor(readonly page: Page) {}

  async goto(): Promise<void> {
    await this.page.goto("/");
  }

  async expectSignedIn(): Promise<void> {
    await expect(this.userMenu).toBeVisible();
  }
}
import { type Page } from "@playwright/test";

import { HomePage } from "./homePage.ts";

/** Ported from the legacy suite; locators unchanged. */
export class LoginPage {
  readonly emailInput = this.page.getByTestId("email");

  readonly passwordInput = this.page.getByTestId("password");

  readonly signInButton = this.page.getByTestId("submit");

  constructor(readonly page: Page) {}

  async goto() {
    await this.page.goto("/");
  }

  async loginViaUI(email: string, password: string) {
    await this.goto();
    await this.emailInput.waitFor({ state: "visible" });
    await this.emailInput.fill(email);
    await this.passwordInput.fill(password);
    await this.signInButton.click();
    /*
     * Asserted on the sidebar rather than on a name or an email: the seed's staff users
     * differ per Saleor image, and the point of this check is that the session took.
     */
    await new HomePage(this.page).expectSignedIn();
