                  onClick={submit}
                  variant="error"
                >
                  <FormattedMessage {...messages.confirmButton} />
                </ConfirmButton>
              </DashboardModal.Actions>
            </DashboardModal.Content>
          );
        }}
      </Form>
    </DashboardModal>
  );
};

